/**
 * **Report** — a write-up drafted from the records, edited by a person and
 * published as frozen versions (projects.md PJ-14, board `projects.report`).
 *
 * The draft is generated by the engine from a template over the question,
 * branches, evidence, verdicts and decisions — nothing invented — and edited
 * here as Markdown. The draft and every version read rendered, cites numbered
 * (`ReportBody`); *Edit* opens the draft's Markdown. *Publish* freezes it as
 * the next version with the dataset versions it cites; earlier versions stay
 * readable, and one whose cited data was retracted since says so. *Markdown* downloads the version as written;
 * *PDF* is the browser's print of it.
 */

import { Textarea } from "@invana/forms";
import {
	Alert,
	AlertDescription,
	AlertTitle,
	Badge,
	Button,
	SegmentedControl,
} from "@invana/ui";
import { ActButton } from "@invana-studio/shell";
import { FormError, RecordRow } from "@invana-studio/ui";
import { Download, Printer, RefreshCw, Save, Send } from "lucide-react";
import { useEffect, useState } from "react";
import {
	useRecordMutations,
	useReportQuery,
	useReportVersionQuery,
} from "../records/queries";
import { plural, shortDate } from "../records/words";
import type { Project } from "../types";
import { Box, Muted } from "./parts";
import { ReportBody } from "./ReportBody";

const MODES = [
	{ value: "read", label: "Read" },
	{ value: "edit", label: "Edit" },
];

function download(name: string, body: string) {
	const url = URL.createObjectURL(new Blob([body], { type: "text/markdown" }));
	const a = document.createElement("a");
	a.href = url;
	a.download = name;
	a.click();
	URL.revokeObjectURL(url);
}

export function ReportTab({
	project,
	refKey,
	frozen,
}: {
	project: Project;
	refKey: { username: string; graphSlug: string; key: string };
	frozen: boolean;
}) {
	const report = useReportQuery(refKey);
	const m = useRecordMutations(refKey);
	const [draft, setDraft] = useState("");
	/** The version being read; null is the draft. */
	const [reading, setReading] = useState<number | null>(null);
	const [mode, setMode] = useState<"read" | "edit">("read");
	const version = useReportVersionQuery(refKey, reading);
	const saved = report.data?.draft ?? "";
	useEffect(() => setDraft(saved), [saved]);

	const versions = [...(report.data?.versions ?? [])].sort(
		(a, b) => b.version - a.version,
	);
	const next = (versions[0]?.version ?? 0) + 1;
	const dirty = draft !== saved;
	const error = m.generate.error ?? m.saveDraft.error ?? m.publish.error;
	const v = version.data;

	return (
		<div className="grid min-w-0 grid-cols-[2fr_1fr] gap-3 p-3">
			<Box
				title="Report"
				count={reading === null ? "draft" : `v${reading}`}
				actions={
					reading === null && !frozen ? (
						<>
							{saved || dirty ? (
								<SegmentedControl
									options={MODES}
									value={mode}
									onValueChange={(v) => setMode(v as "read" | "edit")}
								/>
							) : null}
							<ActButton
								area="work"
								variant="ghost"
								size="sm"
								disabled={m.generate.isPending}
								onClick={() => m.generate.mutate()}
							>
								<RefreshCw />
								{saved
									? "Regenerate from the records"
									: "Draft from the records"}
							</ActButton>
							<ActButton
								area="work"
								variant="outline"
								size="sm"
								disabled={!dirty || m.saveDraft.isPending}
								onClick={() => m.saveDraft.mutate(draft)}
							>
								<Save />
								Save draft
							</ActButton>
						</>
					) : null
				}
			>
				{reading === null ? (
					<div className="flex flex-col gap-2 p-3">
						{(saved || dirty) && (mode === "read" || frozen) ? (
							<ReportBody body={draft} />
						) : saved || dirty ? (
							<Textarea
								aria-label="Report draft"
								rows={22}
								value={draft}
								disabled={frozen}
								onChange={(e) => setDraft(e.target.value)}
								className="font-mono"
							/>
						) : (
							<Muted>
								No draft yet. Draft it from the records — the question, the
								branches, the evidence for and against, the verdicts and the
								decisions — then edit it before you publish.
							</Muted>
						)}
						{report.data?.draft_updated_at ? (
							<p className="text-sm text-muted-foreground">
								Draft · last edited {shortDate(report.data.draft_updated_at)}
								{dirty ? " · unsaved changes" : ""}
							</p>
						) : null}
						<FormError error={error as Error | null} />
					</div>
				) : v ? (
					<div className="flex flex-col gap-2 p-3">
						{v.retracted.length ? (
							<Alert variant="destructive">
								<AlertTitle>Cites retracted data</AlertTitle>
								<AlertDescription>
									{v.retracted.join(", ")}{" "}
									{v.retracted.length === 1 ? "was" : "were"} retracted after v
									{v.version} was published. The version is kept as it was;
									publish a new one that no longer rests on it.
								</AlertDescription>
							</Alert>
						) : null}
						<p className="text-sm text-muted-foreground">
							v{v.version} · published {shortDate(v.published_at)} · cites{" "}
							{plural(v.cites.length, "dataset version")}
						</p>
						<ReportBody body={v.body} />
					</div>
				) : (
					<Muted>Reading v{reading}…</Muted>
				)}
			</Box>
			<div className="flex flex-col gap-3">
				<Box title="Versions" count={versions.length + 1}>
					<ul>
						<li>
							<RecordRow
								active={reading === null}
								onClick={() => setReading(null)}
								tone="info"
								title={`v${next} · draft`}
								subtitle={
									report.data?.draft_updated_at
										? shortDate(report.data.draft_updated_at)
										: "not written"
								}
								status="draft"
							/>
						</li>
						{versions.map((x) => (
							<li key={x.version}>
								<RecordRow
									active={reading === x.version}
									onClick={() => setReading(x.version)}
									tone="success"
									title={`v${x.version} · published`}
									subtitle={shortDate(x.published_at)}
									status="published"
									statusTone="success"
								/>
							</li>
						))}
					</ul>
				</Box>
				<Box title="Export">
					<div className="flex flex-wrap gap-2 p-3">
						<Button
							variant="outline"
							size="sm"
							disabled={reading === null ? !draft : !v}
							onClick={() => window.print()}
						>
							<Printer />
							PDF
						</Button>
						<Button
							variant="outline"
							size="sm"
							disabled={reading === null ? !draft : !v}
							onClick={() =>
								download(
									`${project.key}-${reading === null ? "draft" : `v${reading}`}.md`,
									reading === null ? draft : (v?.body ?? ""),
								)
							}
						>
							<Download />
							Markdown
						</Button>
						{frozen ? null : (
							<ActButton
								area="work"
								size="sm"
								disabled={!saved || dirty || m.publish.isPending}
								title={
									dirty
										? "Save the draft first — what is published is the saved draft."
										: undefined
								}
								onClick={() =>
									m.publish.mutate(undefined, {
										onSuccess: (pub) => setReading(pub.version),
									})
								}
							>
								<Send />
								Publish v{next}
							</ActButton>
						)}
					</div>
					{versions.length ? null : (
						<p className="px-3 pb-3">
							<Badge variant="outline" tone="muted" size="xs">
								nothing published yet
							</Badge>
						</p>
					)}
				</Box>
			</div>
		</div>
	);
}
